var sinkTotal atomic.Int64

func BenchmarkCacheGet(b *testing.B) {
    cache := NewCache(1000)
    populateCache(cache)
    b.ResetTimer()
    b.RunParallel(func(pb *testing.PB) {
        var acc int // goroutine-local: nothing shared while the timer runs
        for pb.Next() {
            v, _ := cache.Get("key-42")
            if v != nil {
                acc++
            }
        }
        sinkTotal.Add(int64(acc)) // one atomic publish per goroutine, after the loop
    })
}
